// Offline Chromium regression for all THREE public entrypoints.
// API response is the exact common source-only payload generated by the
// deterministic Worker recovery module. No live AI calls or secrets.
import assert from "node:assert/strict";
import {createServer} from "node:http";
import {readFile} from "node:fs/promises";
import path from "node:path";
import {chromium} from "playwright-core";
import {
  historicalJudicialResearchRecovery,
  historicalJudicialResearchRecoveryPayload
} from "../src/historical-judicial-research-recovery.js";

const query="сакам да те замолам да ми направиш еден труд на тема: Судски пресуди во макеоднското судство во периодот оод 1991 до 2026 година, со почит, Трпе";
const recovery=historicalJudicialResearchRecovery(query,{ok:false,error:"openai_incomplete_response",status:503});
assert.ok(recovery,"source registry unavailable");
const root=process.cwd();
const workerOrigin="https://ai-advokat-github-io.aiadvokat16.workers.dev";
const mime={".html":"text/html; charset=utf-8",".js":"text/javascript; charset=utf-8",".mjs":"text/javascript; charset=utf-8",".json":"application/json",".css":"text/css; charset=utf-8",".svg":"image/svg+xml",".webp":"image/webp"};
const server=createServer(async(req,res)=>{
  let pathname;
  try{pathname=decodeURIComponent(new URL(req.url,"http://127.0.0.1").pathname);}catch{res.writeHead(400);res.end();return;}
  if(pathname.endsWith("/"))pathname+="index.html";
  const file=path.resolve(root,"."+pathname);
  if(!file.startsWith(root+path.sep)){res.writeHead(403);res.end();return;}
  try{const data=await readFile(file);res.writeHead(200,{"content-type":mime[path.extname(file)]||"application/octet-stream","cache-control":"no-store"});res.end(data);}
  catch{res.writeHead(404);res.end("missing");}
});
let browser;
async function exercise(localOrigin,entry){
  const context=await browser.newContext({locale:"mk-MK",serviceWorkers:"block",viewport:{width:1280,height:800}});
  const page=await context.newPage();
  let calls=0,apiPath=null;
  await page.route(workerOrigin+"/**",async route=>{
    const request=route.request(),url=new URL(request.url()),pathname=url.pathname;
    if(request.method()==="POST" && ["/api/chat","/api/bot"].includes(pathname)){
      calls++;apiPath=pathname;
      const payload=historicalJudicialResearchRecoveryPayload(recovery,{
        from:pathname==="/api/bot"?"openai":"workers_ai",
        failure:{ok:false,error:"openai_incomplete_response",status:503},
        providerCalls:1,trainingOpen:true,used:1,quota:20
      });
      await route.fulfill({
        status:200,contentType:"application/json",
        headers:{"access-control-allow-origin":"*","access-control-allow-headers":"authorization,content-type"},
        body:JSON.stringify(payload)
      });
    }else if(pathname==="/bot/" || pathname==="/bot/index.html"){
      await route.fulfill({status:200,contentType:"text/html",body:await readFile(path.join(root,"bot/index.html"))});
    }else if(pathname.startsWith("/assets/") || pathname.startsWith("/data/")){
      const file=path.resolve(root,"."+pathname);
      if(!file.startsWith(root+path.sep)){await route.fulfill({status:403,body:"forbidden"});return;}
      try{
        const bytes=await readFile(file);
        await route.fulfill({status:200,contentType:mime[path.extname(file)]||"application/octet-stream",body:bytes});
      }catch{await route.fulfill({status:404,body:"missing"});}
    }else{
      await route.fulfill({
        status:200,contentType:"application/json",
        headers:{"access-control-allow-origin":"*"},
        body:'{"ok":true,"capabilities":{},"trainingOpen":true}'
      });
    }
  });
  const route=entry==="academy"?"/academy/index.html":entry==="external"?"/bot/index.html":"/index.html";
  await page.goto(localOrigin+route,{waitUntil:"domcontentloaded",timeout:35000});
  let botFrame=null;
  if(entry==="academy"){
    await page.locator("#academyChatLaunch").click();
    botFrame=page.frameLocator("#academyChatDialog iframe");
    await botFrame.locator("#question").waitFor({state:"visible",timeout:25000});
  }else if(entry==="external"){
    await page.waitForFunction(()=>window.AIAdvokatCoreReady===true,null,{timeout:25000});
  }else{
    await page.locator("#aiChatInput").waitFor({state:"visible",timeout:25000});
  }
  if(entry==="main"){
    await page.evaluate(text=>{
      const input=document.querySelector("#aiChatInput");
      input.value=text;
      input.dispatchEvent(new Event("input",{bubbles:true}));
      document.querySelector("#aiChatSend").click();
    },query);
  }else{
    const scope=entry==="academy"?botFrame:page;
    await scope.locator("#question").fill(query);
    await scope.locator("#send").click();
  }
  const marker="РАБОТНА ИСТРАЖУВАЧКА РАМКА";
  const target=entry==="academy"?botFrame:page;
  await target.getByText(marker,{exact:false}).first().waitFor({state:"visible",timeout:25000});
  const body=await target.locator("body").innerText();
  assert.ok(body.includes("НЕ готов или рецензиран труд"),"Research-only disclosure missing: "+entry);
  assert.ok(body.includes("1991–2026"),"Requested years missing: "+entry);
  assert.ok(body.includes("Врховен суд"),"Source groups not presented: "+entry);
  assert.ok(!body.includes("AI одговор не е издаден"),"Source recovery hidden by generic 503: "+entry);
  assert.equal(calls,1,"One request only; no recovery model calls: "+entry);
  assert.equal(apiPath,entry==="main"?"/api/chat":"/api/bot","Wrong shared Worker route: "+entry);
  await context.close();
  return {entry,apiPath,calls,status:"VISIBLE_CORPUS_RESEARCH_OUTLINE_NO_MODEL"};
}
try{
  await new Promise(resolve=>server.listen(0,"127.0.0.1",resolve));
  const origin="http://127.0.0.1:"+server.address().port;
  browser=await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE||undefined,headless:true,args:["--no-sandbox","--disable-dev-shm-usage"]});
  const results=[];
  for(const entry of ["main","external","academy"])results.push(await exercise(origin,entry));
  console.log("THREE BOT BROWSER PASS",JSON.stringify(results));
}catch(error){
  console.error("THREE BOT BROWSER FAIL",String(error?.stack||error));
  process.exitCode=1;
}finally{
  await browser?.close().catch(()=>{});
  await new Promise(resolve=>server.close(resolve));
}
